 assert json.loads((ROOT/'prepublication_requirement_audit.json').read_text())['passed'];c=json.loads((ROOT/'scientific_conclusion.json').read_text());label=c['classification'];base='validation_artifacts/stage1_issue21_20261114';perturb=json.loads((ROOT/'perturbation_analysis.json').read_text());censored=sum(x['censored'] for x in perturb)
 lines=['# Issue21: closed-loop mirror first-deviation diagnosis','',f'Completed25 prescribed diagnostic jobs; outcome **{label}**. No training, reward/default changes or parameter scan.','',c['recommendation'],'This recommendation is not implemented in this issue.','', '## Scope','', '- Same five final issue19 sym_wrap policies and exact issue20 strict symmetric USD.','- Stand and0.5m/s, paired phases0/10,1000steps,16 environments and independent num_envs1 repeats for every training seed.','- Open-loop200steps, same saved k0 action sequence and mirrored actions, fixed suspended root/no contact and normal ground, both environment counts.','- Signed yaw velocity perturbations0.01/0.05/0.2rad/s, first0.2s,1024 environments, eval seed1, five training seeds.',f'- Perturbation trial count30720; full-duration slope-censored trials{censored}. All per-seed sign counts, per-environment slopes and censored denominators are retained.','', '## Evidence and interpretation','', 'Frozen rules prioritize O, then distinguish N/H where all required evidence supports them; mixed results remain other. Every observation/action/root/joint/torque/body-contact component has signed traces and first1e-6/1e-4/1e-2 threshold records. Actual joint names/env IDs triggering O at1e-5 are retained separately.','', 'Measured PhysX projected active joint force is distinguished from the approximate implicit-PD estimate and explicit actuation input. Pure implicit-drive torque is not separately exposed by the installed API. Fixed suspension changes the diagnostic fixture only; no default robot/production configuration changes.','', 'Each command/phase/condition has its own fresh process. Exact parent issue20 initial states are restored; num_envs1 matches env0 of16, with ground world origins also matched. Air restores the matched joint state at its fixed suspended anchor. Five independent unperturbed controls provide the matching perturbation reference. Prior sequential sampling and approximate-torque versions are retained remotely with separate computation ledgers.','',f'- [Full results and analysis](../{base}/results.md).',f'- [All component crossings](../{base}/first_component_crossings.csv), [all case/seed records](../{base}/pair_analysis.json), [perturbation signs/slopes](../{base}/perturbation_analysis.json).',f'- [Concrete O components](../{base}/O_trigger_components.json), [independent protocol audit](../{base}/independent_protocol_audit.json), [independent crossings audit](../{base}/independent_component_crossing_audit.json).',f'- [Frozen classification](../{base}/classification_rules.json), [source/input Git object bindings](../{base}/existing_issue20_input_objects.json), [lossless restore](../{base}/RESTORE.md).','', '## Colored exact-state videos','']
 for command in ['stand','forward_05']:
  for phase in [0,10]:lines.append(f'- {command} k{phase}: [front](../{base}/videos/video_{command}_k{phase}_front.mp4), [side](../{base}/videos/video_{command}_k{phase}_side.mp4).')
 lines+=['',f'[Joint color legend](../{base}/joint_colors.json). Fixed training seed1/eval1/env0 from16-env closed-loop traces; source pose timing50fps20s, no dynamics integration, zero display velocities. Front/side follow translation and heading. HumanML3D NPY:N/A, velocity commands rather than retargeted source motion.','', 'Eleven scientific figures, four contact sheets and at least24 full-resolution frames are actually reviewed before archive acceptance.','', 'Ground-open final trajectories continue physically for200 steps with fall conditions recorded and automatic reset suppressed, verified by episode counters. Rejected reset-contaminated ground-open samples are separately logged. Five completed instrumentation-v1 jobs and an interrupted sixth remain separate from formal denominators after correcting approximate PD torque semantics; the computation/correction ledger is retained. Historical issue17/19 failures and issue20 required stop stay preserved. SuperMimic remains stopped. Project records use Notion; no Linear synchronization.']
 (REPO/'docs/stage1_issue21_20261114.md').write_text('\n'.join(lines)+'\n');p=REPO/'README.md';s=p.read_text();old=[x for x in s.splitlines() if x.startswith('| Isaac Lab stage1 velocity walking |')];assert len(old)==1;state=f'Issue21 diagnostic complete:25 jobs, zero training, classification {label}; no default promotion. Historical issue17/19 acceptance remains FAILED.';s=s.replace(old[0],f'| Isaac Lab stage1 velocity walking | {state} | [Issue21 report](docs/stage1_issue21_20261114.md), [raw analysis]({base}/results.md) |');start='<!-- ISSUE21_STATUS_START -->';end='<!-- ISSUE21_STATUS_END -->';section=start+'\n'+state+' Closed/open-loop first-deviation traces, measured joint-force semantics, yaw perturbation distributions, independent component audits and colored front/side videos are retained. [Full report](docs/stage1_issue21_20261114.md).\n'+end
